segments.en:
letter-spacing: 0.04em;

margin-bottom: 0.3rem;

font-family: 'Cinzel', serif;

font-size: 1.1rem;

font-weight: 400;

color: var(--gold);

text-align: center;

letter-spacing: 0.12em;

margin-bottom: 2.5rem;

.ruling {

.intro-block p{text-indent:0;margin-bottom:8px;font-size:17px}

.summation{background:linear-gradient(135deg,#f5f0e8 0%,#ebe5d8 100%);border:2px solid var(--border);border-radius:8px;padding:25px 30px;margin:45px 0 20px}

.summation-header{text-align:center;font-size:14px;letter-spacing:3px;text-transform:uppercase;color:var(--accent);margin-bottom:15px;font-weight:700}

.summation p{font-size:16px;text-indent:0;margin-bottom:10px;color:var(--text-light)}

padding: 0.5em 1em; margin: 1.2em auto; max-width: 700px;

/* ── Section numbers ── */

.section-num {

font-weight: bold; font-size: 1.13em; color: #7a3b00;

display: block; margin: 1.6em 0 0.3em;

/* ── Key terms ── */

.ht { font-style: italic; color: #2c5f8a; } /* Hebrew term */

.kab { font-style: italic; color: #5a2d7a; } /* kabbalistic term */

.em { font-weight: bold; } /* emphasis */

.src { font-size: 0.88em; color: #888; } /* source citation */

/* ── Play on words / root ── */

.root { font-size: 0.82em; color: #6b4c0e; font-variant: small-caps; }

/* ── Acronym highlight ── */

.acro {

font-weight: bold; font-size: 1.08em;

color: #b5390e; text-decoration: underline dotted #b5390e;

/* ── Quote block (Talmud / Zohar / Scripture verse as subtitle) ── */

.verse-subtitle {

display: block; text-align: center;

font-size: 1.1em; font-style: italic; font-weight: bold;

color: #2c5a2c; background: #f0faf0;

border-top: 2px solid #4caf50; border-bottom: 2px solid #4caf50;

padding: 0.5em 1.2em; margin: 1.4em auto 0.8em;

max-width: 750px;

/* ── Inline verse ── */

.verse { font-style: italic; color: #2c5a2c; }
